  if not exists (select 1 from public.staff where display_name = r->>'name' and kind = r->>'kind') then
    insert into public.staff (display_name, kind, sort_order) values (r->>'name', r->>'kind', (r->>'sort')::int) returning id into sid;
    insert into public.staff_private (staff_id, female, is_leader, ahmash_rank, leader_priority, no_nights, manual_only, only_long_weekend, latest_end_hour)
      values (sid, (r->>'female')::boolean, (r->>'leader')::boolean, (r->>'ahmash')::int, nullif(r->>'prio','')::int, (r->>'no_nights')::boolean, (r->>'manual_only')::boolean, (r->>'only_long')::boolean, nullif(r->>'latest_end','')::int);
  end if;
end loop;
-- personal conditions that are not simple flags (as data):
select id into sid from public.staff where display_name = 'רועי' and kind = 'instructor';
select id into tid from public.staff where display_name = 'יובל' and kind = 'instructor';
if sid is not null and tid is not null and not exists (select 1 from public.staff_constraints where staff_id = sid) then
  insert into public.staff_constraints (staff_id, kind, strength, params) values
    (sid, 'prefer_nights', 'soft', '{}'),
    (sid, 'thursday_afternoon_only_with', 'hard', jsonb_build_object('staff_id', tid)),
    (sid, 'other_shifts_with', 'strong', jsonb_build_object('staff_id', tid));
end if;
end $$;